MATCH (item:PlantItem {tag: "E-2-6"})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: 'T-3-1'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: "E-2-1"})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (v:PlantItem:CheckValve)
WHERE toString(v.unit_id) = "5"
RETURN count(v) AS count, collect(v.tag) AS tags;

MATCH (s:PlantItem {tag: 'TK-4-1'}), (t:PlantItem {tag: 'TK-1-1'})
MATCH p = shortestPath((s)-[:send_to*]->(t))
RETURN [n IN nodes(p) WHERE n:Equipment OR n:OperatedValve OR n:BallValve OR n:CheckValve OR n:GlobeValve | n.tag] AS path_tags;
